    routes = [two_opt(r) for r in routes]

    # Inter-route relocate improvement
    improved = True
    while improved:
        improved = False
        for i in range(len(routes)):
            for j in range(len(routes)):
                if i == j:
                    continue
                ri = routes[i]
                rj = routes[j]
                li = route_demand(ri)
                lj = route_demand(rj)
                for pos in range(len(ri)):
                    c = ri[pos]
                    dc = demand.get(c, 0)
                    if lj + dc > capacity:
                        continue
                    prev_i = depot_id if pos == 0 else ri[pos - 1]
                    next_i = depot_id if pos == len(ri) - 1 else ri[pos + 1]
                    remove_gain = dist(prev_i, c) + dist(c, next_i) - dist(prev_i, next_i)

                    best_ins = None
                    best_delta = None
                    for k in range(len(rj) + 1):
                        prev_j = depot_id if k == 0 else rj[k - 1]
                        next_j = depot_id if k == len(rj) else rj[k]
                        add_cost = dist(prev_j, c) + dist(c, next_j) - dist(prev_j, next_j)
                        delta = add_cost - remove_gain
                        if best_delta is None or delta < best_delta:
                            best_delta = delta
                            best_ins = k
                    if best_delta is not None and best_delta < -1e-12:
                        new_ri = ri[:pos] + ri[pos + 1:]
                        new_rj = rj[:best_ins] + [c] + rj[best_ins:]
                        routes[i] = new_ri
                        routes[j] = new_rj
                        improved = True
                        break
                if improved:
                    break
            if improved:
                break

    # Final cleanup: remove empty routes, re-optimize
    routes = [two_opt(r) for r in routes if r]
    return routes
